<?php
// Единый серверный API Клуба Барберов. PHP 7.4+ / MySQL 5.7+.
declare(strict_types=1);
session_start();
header('Content-Type: application/json; charset=utf-8');
header('Cache-Control: no-store');
function out($data, int $code=200): void { http_response_code($code); echo json_encode($data, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); exit; }
function body(): array { $v=json_decode(file_get_contents('php://input'), true); return is_array($v)?$v:[]; }
function db(): PDO { static $pdo=null; if($pdo) return $pdo; $f=__DIR__.'/config.php'; if(!file_exists($f)) out(['error'=>'Не найден config.php. Скопируйте config.php.example и заполните доступы MySQL.'],500); $c=require $f; try { $pdo=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); } catch(Throwable $e){ out(['error'=>'Не удалось подключиться к MySQL. Проверьте config.php.'],500); } return $pdo; }
function admin(): void { if(empty($_SESSION['admin_id'])) out(['error'=>'Требуется вход администратора'],401); }
function clean($v,$n=255){ return mb_substr(trim((string)$v),0,$n); }
$action=$_GET['action']??''; $pdo=db();
if($action==='status'){ out(['ok'=>true,'first'=>((int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn()===0),'logged'=>!empty($_SESSION['admin_id'])]); }
if($action==='register'){
 $b=body(); $email=strtolower(clean($b['email']??'',190)); $pass=(string)($b['password']??''); if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<10) out(['error'=>'Проверьте почту и пароль (минимум 10 символов).'],400);
 try{$pdo->beginTransaction(); $count=(int)$pdo->query('SELECT COUNT(*) FROM admins FOR UPDATE')->fetchColumn(); if($count!==0){$pdo->rollBack();out(['error'=>'Первый администратор уже зарегистрирован.'],403);} $st=$pdo->prepare('INSERT INTO admins(email,password_hash) VALUES(?,?)');$st->execute([$email,password_hash($pass,PASSWORD_DEFAULT)]);$id=(int)$pdo->lastInsertId();$pdo->commit();$_SESSION['admin_id']=$id;out(['ok'=>true]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();out(['error'=>'Регистрация не выполнена. Возможно, первый администратор уже создан.'],409);}
}
if($action==='login'){ $b=body();$st=$pdo->prepare('SELECT id,password_hash FROM admins WHERE email=?');$st->execute([strtolower(clean($b['email']??'',190))]);$u=$st->fetch();if(!$u||!password_verify((string)($b['password']??''),$u['password_hash']))out(['error'=>'Неверная почта или пароль'],401);session_regenerate_id(true);$_SESSION['admin_id']=(int)$u['id'];out(['ok'=>true]); }
if($action==='logout'){$_SESSION=[];session_destroy();out(['ok'=>true]);}
if($action==='lead'){$b=body();$name=clean($b['name']??'',120);$contact=clean($b['contact']??'',190);if(mb_strlen($name)<2||mb_strlen($contact)<5)out(['error'=>'Некорректная заявка'],400);$st=$pdo->prepare('INSERT INTO leads(name,contact,source,visitor_id,ref,utm_source,utm_medium,utm_campaign,utm_content,utm_term) VALUES(?,?,?,?,?,?,?,?,?,?)');$st->execute([$name,$contact,clean($b['source']??'',200),clean($b['visitor_id']??'',80),clean($b['ref']??'',80),clean($b['utm_source']??'',80),clean($b['utm_medium']??'',80),clean($b['utm_campaign']??'',80),clean($b['utm_content']??'',80),clean($b['utm_term']??'',80)]);out(['ok'=>true]);}
if($action==='event'){$b=body();$allowed=['pageview','cta_click','join_click','pay_click','lead_submit','pricing_view','case_view'];$ev=clean($b['event']??'',40);if(!in_array($ev,$allowed,true))out(['ok'=>true]);$meta=isset($b['meta'])?json_encode($b['meta'],JSON_UNESCAPED_UNICODE):null;$st=$pdo->prepare('INSERT INTO events(visitor_id,session_id,event,plan,click_id,ref,utm_source,utm_medium,utm_campaign,utm_content,utm_term,path,referrer,meta) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute([clean($b['visitor_id']??'',80),clean($b['session_id']??'',80),$ev,clean($b['plan']??'',30),clean($b['click_id']??'',40),clean($b['ref']??'',80),clean($b['utm_source']??'',80),clean($b['utm_medium']??'',80),clean($b['utm_campaign']??'',80),clean($b['utm_content']??'',80),clean($b['utm_term']??'',80),clean($b['path']??'',200),clean($b['referrer']??'',200),$meta]);out(['ok'=>true]);}
if($action==='is_admin'){out(!empty($_SESSION['admin_id']));}
if($action==='rpc' && ($_GET['name']??'')==='is_admin'){out(!empty($_SESSION['admin_id']));}
if($action==='rpc') { admin(); $name=$_GET['name']??''; $days=(isset(body()['p_days'])?body()['p_days']:30); $since=($days==='all'||$days===null)?null:date('Y-m-d H:i:s',time()-(int)$days*86400);
 if($name==='partner_stats'){ $sql="SELECT p.slug, COUNT(DISTINCT e.visitor_id) visitors, COUNT(DISTINCT l.id) leads, COUNT(DISTINCT pay.id) buyers, COALESCE(SUM(pay.amount),0) revenue FROM partners p LEFT JOIN events e ON e.ref=p.slug AND e.event='pageview' "; $sql.="LEFT JOIN leads l ON l.ref=p.slug LEFT JOIN payments pay ON pay.source=p.slug GROUP BY p.id"; out($pdo->query($sql)->fetchAll()); }
 if($name==='partner_daily') out([]);
 if($name==='funnel_by_source') { $rows=$pdo->query("SELECT COALESCE(NULLIF(ref,''),NULLIF(utm_source,''),'direct') src, COUNT(DISTINCT CASE WHEN event='pageview' THEN visitor_id END) visitors, COUNT(DISTINCT CASE WHEN event IN ('cta_click','join_click') THEN visitor_id END) clickers, COUNT(DISTINCT CASE WHEN event='pay_click' THEN visitor_id END) payclickers, 0 leads, 0 buyers, 0 revenue FROM events GROUP BY src")->fetchAll(); out($rows); }
 out([]); }
admin();
$path=trim($_GET['path']??''); [$table,$query]=array_pad(explode('?', $path,2),2,''); if(!in_array($table,['partners','leads','payments'],true))out(['error'=>'Неизвестный раздел'],404);
$method=$_SERVER['REQUEST_METHOD']; parse_str($query,$q); $days=$q['created_at']??$q['paid_at']??null;
if($method==='GET'){$sql='SELECT * FROM '.$table; $params=[]; if(isset($q['id'])&&preg_match('/^eq\.(\d+)$/',$q['id'],$m)){$sql.=' WHERE id=?';$params[]=(int)$m[1];} if(isset($q['created_at'])&&preg_match('/^gte\.(.+)$/',$q['created_at'],$m)){$sql.=' WHERE created_at>=?';$params[]=$m[1];} if(isset($q['paid_at'])&&preg_match('/^gte\.(.+)$/',$q['paid_at'],$m)){$sql.=' WHERE paid_at>=?';$params[]=$m[1];} $order=$q['order']??'created_at.desc';$col=preg_match('/^(created_at|paid_at|id|name)$/',explode('.',$order)[0])?explode('.',$order)[0]:'id';$dir=(strpos($order,'.asc')!==false)?'ASC':'DESC';$sql.=" ORDER BY $col $dir";if(isset($q['limit']))$sql.=' LIMIT '.min(500,(int)$q['limit']);$st=$pdo->prepare($sql);$st->execute($params);out($st->fetchAll());}
if($method==='POST'){$b=body();$rows=isset($b[0])?$b:[$b];$out=[];foreach($rows as $r){if($table==='partners'){$st=$pdo->prepare('INSERT INTO partners(name,slug,active) VALUES(?,?,1)');$st->execute([clean($r['name']??'',80),clean($r['slug']??'',40)]);$out[]=['id'=>(int)$pdo->lastInsertId(),'name'=>$r['name'],'slug'=>$r['slug'],'active'=>1,'created_at'=>date('Y-m-d H:i:s')];}else{if($table!=='payments')out(['error'=>'Операция запрещена'],403);$st=$pdo->prepare('INSERT INTO payments(source,plan,amount,comment,paid_at,lead_id) VALUES(?,?,?,?,?,?)');$st->execute([$r['source']??null,$r['plan']??'other',(float)($r['amount']??0),$r['comment']??null,$r['paid_at']??date('Y-m-d'),$r['lead_id']??null]);$out[]=['id'=>(int)$pdo->lastInsertId()];}}out($out);}
if($method==='PATCH'&&$table==='partners'){if(!preg_match('/^eq\.(\d+)$/',$q['id']??'',$m))out(['error'=>'Некорректный ID'],400);$b=body();$st=$pdo->prepare('UPDATE partners SET active=? WHERE id=?');$st->execute([!empty($b['active'])?1:0,(int)$m[1]]);out(['ok'=>true]);}
if($method==='DELETE'){if(!preg_match('/^eq\.(\d+)$/',$q['id']??'',$m))out(['error'=>'Некорректный ID'],400);$st=$pdo->prepare('DELETE FROM '.$table.' WHERE id=?');$st->execute([(int)$m[1]]);out(['ok'=>true]);}
out(['error'=>'Метод не поддерживается'],405);
